local ChiselBladeMaker = {}
local PRODUCTS = {
    iron_chisel_blade = { name = "Železno rezilo za dleto", ironCost = 5, woodCost = 1, leatherCost = 1, time = 5, cost = 190, prestige = 4, happiness = 2, description = "Železno rezilo za ostra dleta." },
    bronze_chisel_blade = { name = "Bronasto rezilo za dleto", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 460, prestige = 6, happiness = 3, description = "Bronasto rezilo za natančno rezkanje." },
    silver_chisel_blade = { name = "Srebrno rezilo za dleto", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1110, prestige = 11, happiness = 4, description = "Srebrno rezilo za plemiške mizarje." },
    gilded_chisel_blade = { name = "Pozlačeno rezilo za dleto", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2380, prestige = 20, happiness = 5, description = "Pozlačeno rezilo za dvorne mizarje." },
    jewel_set_chisel_blade = { name = "Draguljasto rezilo za dleto", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 5100, prestige = 36, happiness = 7, description = "Draguljasto rezilo za kraljevske mizarje." },
    royal_sovereign_chisel_blade = { name = "Kraljevski suvereno rezilo za dleto", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10900, prestige = 69, happiness = 13, description = "Suvereno rezilo z biseri za krono." },
}
local BUILDINGS = {
    chiselblade_workshop = { name = "Rezilna delavnica", cost = { gold = 370, wood = 175, stone = 145, iron = 11 }, upkeep = 7, qualityBonus = 5 },
    chiselblade_house = { name = "Rezilna hiša", cost = { gold = 1285, wood = 360, stone = 285, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_chiselblade_atelier = { name = "Mojstrski rezilni atelje", cost = { gold = 3200, wood = 420, stone = 540, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_chiselblade_palace = { name = "Suverena rezilna palača", cost = { gold = 13600, wood = 650, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
ChiselBladeMaker.ironStock = 18; ChiselBladeMaker.bronzeStock = 14; ChiselBladeMaker.woodStock = 10; ChiselBladeMaker.leatherStock = 8; ChiselBladeMaker.silverStock = 8; ChiselBladeMaker.goldStock = 6; ChiselBladeMaker.jewelStock = 4; ChiselBladeMaker.pearlStock = 4
ChiselBladeMaker.productStock = {}; ChiselBladeMaker.buildings = {}; ChiselBladeMaker.maker = nil; ChiselBladeMaker.activeMaking = {}; ChiselBladeMaker.totalProducts = 0; ChiselBladeMaker.dayTimer = 0
function ChiselBladeMaker.init() ChiselBladeMaker.ironStock=18; ChiselBladeMaker.bronzeStock=14; ChiselBladeMaker.woodStock=10; ChiselBladeMaker.leatherStock=8; ChiselBladeMaker.silverStock=8; ChiselBladeMaker.goldStock=6; ChiselBladeMaker.jewelStock=4; ChiselBladeMaker.pearlStock=4; ChiselBladeMaker.productStock={}; ChiselBladeMaker.buildings={}; ChiselBladeMaker.maker=nil; ChiselBladeMaker.activeMaking={}; ChiselBladeMaker.totalProducts=0; ChiselBladeMaker.dayTimer=0; print("[ChiselBladeMaker] Royal Chisel Blade Maker System initialized (6 products, 4 buildings)") end
function ChiselBladeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChiselBladeMaker.maker={name=n or ("Rezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezar najet: %s (spretnost: %d)",ChiselBladeMaker.maker.name,s),"success") end; return true end
function ChiselBladeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChiselBladeMaker.build(id) local ok,e=ChiselBladeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChiselBladeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChiselBladeMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChiselBladeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChiselBladeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ChiselBladeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ChiselBladeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ChiselBladeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ChiselBladeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ChiselBladeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChiselBladeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChiselBladeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChiselBladeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChiselBladeMaker.buildings==0 then return false,"Potrebna rezilna delavnica" end; if not ChiselBladeMaker.maker then return false,"Potreben rezar" end; return true end
function ChiselBladeMaker.make(pt,qty) qty=qty or 1; local ok,e=ChiselBladeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ChiselBladeMaker.ironStock=ChiselBladeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ChiselBladeMaker.bronzeStock=ChiselBladeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ChiselBladeMaker.woodStock=ChiselBladeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ChiselBladeMaker.leatherStock=ChiselBladeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ChiselBladeMaker.silverStock=ChiselBladeMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChiselBladeMaker.goldStock=ChiselBladeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ChiselBladeMaker.jewelStock=ChiselBladeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChiselBladeMaker.pearlStock=ChiselBladeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChiselBladeMaker.maker then t=math.max(1,t-math.floor(ChiselBladeMaker.maker.skill/13)) end; table.insert(ChiselBladeMaker.activeMaking,{id="chiselblade_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChiselBladeMaker.completeMaking(m) local q=1.0+(ChiselBladeMaker.getQualityBonus()/100); if ChiselBladeMaker.maker then q=q+(ChiselBladeMaker.maker.skill/140) end; q=math.min(2.5,q); ChiselBladeMaker.productStock[m.productType]=(ChiselBladeMaker.productStock[m.productType] or 0)+m.quantity; ChiselBladeMaker.totalProducts=ChiselBladeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChiselBladeMaker.maker then ChiselBladeMaker.maker.itemsMade=ChiselBladeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ChiselBladeMaker.maker.skill=math.min(100,ChiselBladeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chiselblade.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ChiselBladeMaker.update(dt) if not _G.state then return end; ChiselBladeMaker.dayTimer=ChiselBladeMaker.dayTimer+dt; if ChiselBladeMaker.dayTimer>=30 then ChiselBladeMaker.dayTimer=0; for i=#ChiselBladeMaker.activeMaking,1,-1 do local m=ChiselBladeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChiselBladeMaker.completeMaking(m); table.remove(ChiselBladeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChiselBladeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChiselBladeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChiselBladeMaker.getStats() return {ironStock=ChiselBladeMaker.ironStock,bronzeStock=ChiselBladeMaker.bronzeStock,woodStock=ChiselBladeMaker.woodStock,leatherStock=ChiselBladeMaker.leatherStock,silverStock=ChiselBladeMaker.silverStock,goldStock=ChiselBladeMaker.goldStock,jewelStock=ChiselBladeMaker.jewelStock,pearlStock=ChiselBladeMaker.pearlStock,productStock=ChiselBladeMaker.productStock,numBuildings=#ChiselBladeMaker.buildings,hasMaker=ChiselBladeMaker.maker~=nil,makerName=ChiselBladeMaker.maker and ChiselBladeMaker.maker.name or "—",makerSkill=ChiselBladeMaker.maker and ChiselBladeMaker.maker.skill or 0,activeMaking=#ChiselBladeMaker.activeMaking,totalProducts=ChiselBladeMaker.totalProducts} end
return ChiselBladeMaker
